mapper.select:
SELECT biz.tenant_id AS tenantId, biz.biz_module AS bizModule, biz.business_id AS bizId, pi.instance_id AS wfInstanceId, biz.actual_status AS bizStatus, pi.status AS wfStatus FROM wf_process_instance pi JOIN (
SELECT ${bt.processInstanceIdField} AS process_instance_id, '${bt.module}' AS biz_module, ${bt.idField} AS business_id, ${bt.statusField} AS actual_status, ${bt.businessTable}.tenant_id AS tenant_id FROM ${bt.businessTable} WHERE ${bt.processInstanceIdField} IS NOT NULL AND ${bt.processInstanceIdField} != ''
) biz ON pi.instance_id = biz.process_instance_id AND pi.tenant_id = biz.tenant_id WHERE ( (biz.actual_status IN ('PENDING_APPROVAL','PENDING','APPROVING','IN_APPROVAL') AND pi.status IN ('COMPLETED','CANCELLED')) OR (pi.status = 'RUNNING' AND biz.actual_status IN ('APPROVED','REJECTED','COMPLETED','CANCELLED')) ) AND COALESCE(pi.end_time, pi.start_time, pi.create_time) >= DATE_SUB(NOW(), INTERVAL #{windowDays} DAY)
